'use strict';
const $=id=>document.getElementById(id), panel=$('panel'), dialog=$('box'), main=$('main');
const menu={home:'Home',karakter:'Karakter',skin:'Koleksi Skin',map:'Map',arena:'Lobi Multiplayer',quest:'Quest & Achievement'};
const prefix='nahwuquest-player-v3:',activeKey='nahwuquest-current-v3',adoptKey='nahwuquest-migrated-v3';
const lessons=atlas.flatMap(world=>world.slice(2).map(line=>line.split('|')));
const bank=lessons.map((a,i)=>[[a[5],a[6],a[7],a[8],a[9]],[a[10],a[11],a[12],a[13],a[4]],...tambahan[i].map(s=>s.split('|'))]);
const spots=[18,50,82];let user=null,pos=18,storageOK=true;
function read(key){const raw=localStorage.getItem(key);return raw?JSON.parse(raw):null}
function message(s,bad=false){const el=$('notice');if(el){el.textContent=s;el.className=bad?'warn notice':'success notice'}}
function write(key,obj){const raw=JSON.stringify(obj);localStorage.setItem(key,raw);if(localStorage.getItem(key)!==raw)throw Error('Simpan gagal')}
function failure(){const s='Progres gagal disimpan. Aktifkan penyimpanan situs, lalu coba lagi.';message(s,true);if(dialog.open){let el=$('saveError');if(!el){el=document.createElement('p');el.id='saveError';el.className='warn';el.setAttribute('role','alert');panel.append(el)}el.textContent=s}}
function save(change){try{const fresh=read(prefix+user.id);if(!fresh)throw Error();change(fresh);write(prefix+fresh.id,fresh);user=fresh;return true}catch{failure();return false}}
function players(){return Object.keys(localStorage).filter(k=>k.startsWith(prefix)).map(read).filter(v=>v&&typeof v.name==='string'&&typeof v.id==='string')}
function normalize(s){return s.trim().replace(/\s+/gu,' ').normalize('NFC')}
function identifier(s){return normalize(s).toLocaleLowerCase('id')}
function load(){try{const id=read(activeKey);user=id?read(prefix+id):null;storageOK=true}catch{user=null;storageOK=false}}
function legacy(){if(read(adoptKey))return null;return read('nahwuquest-atlas-v2')||read('nahwuquest-v1')}
function create(name){const old=legacy()||{},done=Array.isArray(old.done)?[...new Set(old.done.filter(n=>Number.isInteger(n)&&n>=0&&n<18))]:[];
 const skin=Number.isInteger(old.skin)&&gates[old.skin]<=done.length?old.skin:0;
 const p={id:crypto.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2),name,done,skin,world:Number.isInteger(old.world)&&atlas[old.world]?old.world:0,steps:{}};
 write(prefix+p.id,p);write(adoptKey,p.id);return p}
function enter(name){try{const n=normalize(name);if(!n||Array.from(n).length>24){message('Masukkan nama dengan panjang 1–24 karakter.',true);return}let p=players().find(v=>identifier(v.name)===identifier(n))||create(n);write(activeKey,p.id);user=p;pos=18;render();message('Berhasil masuk. Progres tersimpan di browser ini.')}catch{failure()}}
function btn(label,action,cls=''){const b=document.createElement('button');b.type='button';b.textContent=label;b.className=cls;b.onclick=action;return b}
function heading(tag,s){const h=document.createElement(tag);h.textContent=s;return h}
function portrait(i){const c=document.createElement('canvas');c.width=22;c.height=26;sprite(c,i);return c}
function show(title){panel.replaceChildren();let h=heading('h2',title);h.id='dialogTitle';panel.append(h);if(!dialog.open)dialog.showModal();dialog.scrollTop=0}
function view(){const route=location.hash.slice(1);return user&&Object.hasOwn(menu,route)?route:'home'}
function go(key){if(location.hash==='#'+key)render();else location.hash=key}
function render(){stopArena();const current=view();$('nav').replaceChildren();for(const [key,label] of Object.entries(menu)){let b=btn(label,()=>go(key),key===current?'active':'');b.disabled=!user&&key!=='home';if(key===current)b.setAttribute('aria-current','page');$('nav').append(b)}
 $('playerInfo').textContent=user?user.name+' · ✦ '+(user.done.length*50+(user.arenaXP||0))+' XP':'Profil pemain';main.replaceChildren();({home,karakter,skin:wardrobe,map:mapView,quest:journal,arena:arenaView})[current]();let el=document.createElement('p');el.id='notice';el.setAttribute('role','status');main.append(el)}
function home(){main.innerHTML='<section class="homeHero"><div><span class="label">ATLAS NAHWU</span><h1>Desa Alif</h1><p>Jelajahi enam wilayah, pecahkan misi bahasa Arab, dan buka pakaian baru untuk karaktermu.</p><b class="tagline">6 WILAYAH · 18 QUEST · 12 SKIN</b></div></section><div class="twocol"><section class="box" id="login"></section><section class="box" id="continue"></section></div>';
 const area=$('login'),side=$('continue');if(!user){area.innerHTML='<h2>Masuk bermain</h2><p>Masukkan nama untuk membuat profil atau kembali sebagai pemain yang sama di browser ini.</p><form id="loginForm"><label>Nama karakter<br><input id="name" maxlength="24" required placeholder="Nama petualang" autocomplete="nickname"></label><button class="gold" type="submit">Masuk</button></form>';side.innerHTML='<h2>Profil tersimpan</h2>';try{const old=legacy();if(old?.name)$('name').value=old.name;let list=players();if(!list.length)side.append(heading('p','Profil pertama akan muncul di sini setelah kamu masuk.'));for(const p of list)side.append(btn(p.name+' · '+p.done.length+' quest',()=>enter(p.name)))}catch{side.append(heading('p','Penyimpanan browser tidak tersedia. Buka situs secara langsung dan izinkan penyimpanan.'))}
 $('loginForm').onsubmit=e=>{e.preventDefault();enter($('name').value)};return}
 area.append(heading('h2','Selamat datang, '+user.name),heading('p',user.done.length+' dari 18 quest selesai · '+gates.filter(v=>v<=user.done.length).length+' skin terbuka'),btn('Jelajahi map →',()=>go('map'),'gold'),btn('Masuk lobi',()=>go('arena')),btn('Ganti pemain',()=>{try{write(activeKey,null);user=null;render()}catch{failure()}}));
 side.append(heading('h2','Lanjutkan quest'));const id=Object.keys(user.steps).map(Number).find(i=>user.steps[i]>0)??lessons.findIndex((a,i)=>!user.done.includes(i));if(id>=0)side.append(heading('p',lessons[id][0]+' · '+atlas[Math.floor(id/3)][0]),btn('Buka quest',()=>lesson(id)));else side.append(heading('p','Semua quest telah selesai. Kamu bisa mengulang latihan melalui jurnal.'))}
function karakter(){main.innerHTML='<span class="label">PROFIL PEMAIN</span><h1>Tampilan Karakter</h1><div class="twocol"><section class="bigSkin" id="look"></section><section class="box"><h2>Nama karakter</h2><p>Nama ini tampil di atas karaktermu saat menjelajah.</p><form id="rename"><label>Nama panggilan<br><input id="newName" required maxlength="24"></label><button class="gold">Simpan nama</button></form></section></div>';
 $('look').append(portrait(user.skin),heading('h2',user.name),heading('p',outfits[user.skin]),heading('p','Rank arena · '+(user.arenaRank||'Perunggu')+' · '+(user.arenaRP||0)+' RP'),btn('Ganti skin',()=>go('skin')));$('newName').value=user.name;
 $('rename').onsubmit=e=>{e.preventDefault();const n=normalize($('newName').value);if(!n){message('Nama tidak boleh kosong.',true);return}try{if(players().some(p=>p.id!==user.id&&identifier(p.name)===identifier(n))){message('Nama ini sudah dipakai profil lain di browser ini.',true);return}}catch{failure();return}
 if(save(p=>p.name=n)){render();message('Nama karakter berhasil disimpan.')}}}
function wardrobe(){main.innerHTML='<span class="label">INVENTARIS</span><h1>Koleksi Skin</h1><p>Pilih pakaian yang sudah terbuka untuk memakainya di semua wilayah.</p><div class="cards" id="skins"></div>';outfits.forEach((s,i)=>{const b=btn('',()=>{if(save(p=>{if(gates[i]<=p.done.length)p.skin=i})){render();message('Skin berhasil dipakai.')}},'skinButton');const body=document.createElement('div');body.append(heading('h3',s),heading('small',i===user.skin?'✓ Dipakai':gates[i]>user.done.length?'Terkunci · '+gates[i]+' quest':'Pakai skin'));b.disabled=i===user.skin||gates[i]>user.done.length;b.append(portrait(i),body);$('skins').append(b)})}
function status(i){return user.steps[i]?'Lanjut · soal '+(user.steps[i]+1)+'/5':user.done.includes(i)?'✓ Selesai · ulangi':'5 soal · 50 XP'}
function questCard(i){const b=btn('',()=>lesson(i),'card');b.append(heading('small','POS '+(i%3+1)),heading('h3',lessons[i][0]),heading('small',status(i)));return b}
function nearest(){return spots.reduce((a,x,j)=>Math.abs(spots[a]-pos)<=Math.abs(x-pos)?a:j,0)}
function walk(v){pos=Math.max(8,Math.min(92,v));$('player').style.left=pos+'%';$('start').textContent='Masuk pos '+(nearest()+1)+' →'}
function mapView(){main.innerHTML='<span class="label">ATLAS NAHWU</span><h1>Map</h1><nav class="atlas" id="atlas" aria-label="Pilih wilayah"></nav><section class="world"><canvas id="land" width="480" height="128"></canvas><span class="label" id="region"></span><h1 id="title"></h1><div id="pins"></div><div id="player" class="player"><span class="name" id="tag"></span></div></section><div id="walk" class="tools"></div><h2 id="theme"></h2><p>Pilih pos di peta atau gerakkan karakter dengan tombol panah.</p><div class="cards" id="cards"></div>';
 let w=user.world;atlas.forEach((m,k)=>{let b=btn((k+1)+'. '+m[0],()=>{if(save(p=>p.world=k)){pos=18;render()}});b.setAttribute('aria-current',k===w);$('atlas').append(b)});$('region').textContent='WILAYAH 0'+(w+1);$('title').textContent=atlas[w][0];$('theme').textContent=atlas[w][1];$('tag').textContent=user.name;$('player').append(portrait(user.skin));landscape(w);
 for(let j=0;j<3;j++){const i=w*3+j,b=btn((user.done.includes(i)?'✓ ':'⚑ ')+(j+1),()=>walk(spots[j]),'pin');b.style.left=spots[j]+'%';b.setAttribute('aria-label','Ke pos '+(j+1)+' '+lessons[i][0]);$('pins').append(b);$('cards').append(questCard(i))}
 const start=btn('',()=>lesson(w*3+nearest()),'gold');start.id='start';$('walk').append(btn('← Kiri',()=>walk(pos-8)),btn('Kanan →',()=>walk(pos+8)),start);walk(pos)}
function journal(){main.innerHTML='<span class="label">JURNAL PEMAIN</span><h1>Quest &amp; Achievement</h1><h2 class="section">Pencapaian</h2><div id="badges"></div><h2 class="section">Daftar quest</h2>';const d=user.done;const stats=[['Langkah Pertama',d.length,1,'quest'],['Penjelajah Atlas',atlas.filter((m,k)=>[0,1,2].every(j=>d.includes(k*3+j))).length,6,'wilayah tuntas'],['Kolektor Skin',gates.filter(g=>g<=d.length).length,12,'skin'],['Ahli Nahwu',d.length,18,'quest']];for(const [name,n,max,unit] of stats){let el=document.createElement('div');el.className='achievement';el.append(heading('strong',(n>=max?'★ ':'☆ ')+name),heading('small',Math.min(n,max)+' / '+max+' '+unit));$('badges').append(el)}
 atlas.forEach((m,k)=>{main.append(heading('h3',m[0]));let g=document.createElement('div');g.className='cards questrow';for(let j=0;j<3;j++)g.append(questCard(k*3+j));main.append(g)})}
function lesson(i){const a=lessons[i];show(a[0]);let example=document.createElement('div');example.className='example';let arab=heading('b',a[1]);arab.className='ar';arab.lang='ar';arab.dir='rtl';example.append(arab,heading('span',a[2]));panel.append(example,heading('h3','Cara membacanya'),heading('p',a[3]),heading('h3','Perhatikan'),heading('p',a[4]),btn(user.steps[i]?'Lanjut ke soal '+(user.steps[i]+1):'Mulai latihan · 5 soal',()=>quiz(i),'gold'))}
function quiz(i){const n=user.steps[i]||0,[q,correct,...rest]=bank[i][n];show(lessons[i][0]);panel.append(heading('small','SOAL '+(n+1)+' / 5'),heading('h3',q));let choices=document.createElement('div');choices.className='choices';let note=heading('p','');note.setAttribute('role','status');panel.append(choices,note);let opts=[correct,...rest.slice(0,2)];for(let j=2;j>0;j--){let k=Math.floor(Math.random()*(j+1));[opts[j],opts[k]]=[opts[k],opts[j]]}
 opts.forEach(x=>{let b=btn(x,()=>{if(x!==correct){b.disabled=true;note.textContent='Belum tepat. '+rest[2]+' Coba lagi.';return}
 const before=user.done.length;if(!save(p=>{if((p.steps[i]||0)!==n)return;if(n<4)p.steps[i]=n+1;else{delete p.steps[i];if(!p.done.includes(i))p.done.push(i)}}))return;
 for(const opt of choices.children)opt.disabled=true;note.textContent='Benar! '+rest[2];render();panel.append(btn(n<4?'Soal berikutnya →':'Lihat hasil →',()=>n<4?quiz(i):result(i,user.done.length>before),'gold'))});choices.append(b)})}
function result(i,fresh){show('Quest selesai');panel.append(heading('p',lessons[i][0]+' · 5 dari 5 soal selesai.'),heading('h3',fresh?'+50 XP':'Latihan ulang selesai'));let reward=fresh?gates.indexOf(user.done.length):-1;if(reward>=0)panel.append(heading('p','Skin baru terbuka: '+outfits[reward]),btn('Lihat skin',()=>{dialog.close();go('skin')}));panel.append(btn('Kembali',()=>dialog.close(),'gold'))}
$('cross').onclick=()=>dialog.close();window.addEventListener('hashchange',()=>{if(dialog.open)dialog.close();render()});
window.addEventListener('storage',e=>{if(!e.key||e.key===activeKey||e.key===prefix+user?.id){if(dialog.open)dialog.close();load();render()}});
document.addEventListener('keydown',e=>{if(view()==='map'&&!dialog.open&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();walk(pos+(e.key==='ArrowLeft'?-8:8))}});
load();render();
